code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    def support(p):
        r, c = p
        return sum(1 for rr in range(max(0, r-2), min(h, r+3))
                   for cc in range(max(0, c-2), min(w, c+3))
                   if grid[rr][cc] not in (0, 5))
    source = max(points, key=support)
    sr, sc = source
    offsets = [(r-sr, c-sc, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 5)]
    out = [row[:] for row in grid]
    for tr, tc in points:
        if (tr, tc) == source:
            continue
        out[tr][tc] = 0
        for dr, dc, color in offsets:
            rr, cc = tr + dr, tc + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
'''
